        bumperInstantIds: [1],
        bumperMode: 'sequential',
      };
      await onAir(h);
      expect(h.palazzo.announced).toEqual([]);
    });

    it('when the successor has an intro', async () => {
      const h = harness({ intro: SONGS[1].id });
      await onAir(h);
      expect(h.palazzo.announced).toEqual([]);
    });

    it('while a clocked flight log runs', async () => {
