      await settle();
      expect(h.palazzo.withdrawals).toBe(1);
    });

    it('when the queue head no longer resolves to a playable song', async () => {
      const h = harness();
      await onAir(h);
      h.engine.handleQueueUpdated(PROGRAM, [
        { id: 'entry-x', itemId: 'missing', enqueuedAt: 1 },
