        ).toEqual([]);
        // Nothing left to withdraw afterwards.
        h.palazzo.start();
        await settle();
        h.engine.handleSequenceUpdated(PROGRAM, {
          ...h.sequence(),
          mode: 'manual',
        });
        await settle();
        expect(h.palazzo.withdrawals).toBe(1);
